#[inductive(combiner_go_to_collecting)]
fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
    // The transition only updates `combiner` from Responding{elems, idx=num_clients}
    // to Collecting{elems: Seq::empty()}. All other fields are unchanged.

    // Prove not_waiting_inv:
    // clients and slots are unchanged, so this follows directly from pre.
    assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle()
        implies !post.slots.index(i) by {
        assert(pre.not_waiting_inv());
    };

    // Prove waiting_inv:
    // In pre, combiner = Responding{..., idx = num_clients}.
    // For any valid i, valid_idx(i) means i < num_clients = idx,
    // but combiner_has requires i >= idx, so pre.combiner_has(i) is always false.
    // Thus pre.waiting_inv gives: client_waiting(i) ==> request_stored(i) || response_stored(i).
    // In post, combiner = Collecting{elems: Seq::empty()}, so post.combiner_has(i) is also false.
    // clients, requests, responses are unchanged, so the same implication holds.
    assert forall |i: nat| #[trigger] post.client_waiting(i)
        implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        assert(pre.waiting_inv());
        // Show pre.combiner_has(i) is false
        assert(pre.combiner.get_Responding_idx() == pre.num_clients);
        assert(!pre.combiner_has(i)) by {
            if pre.combiner_has(i) {
                // combiner_has(i) requires valid_idx(i) && i >= idx
                // valid_idx(i) => i < num_clients = idx => contradiction
                assert(pre.valid_idx(i));
                assert(i >= pre.combiner.get_Responding_idx());
                assert(i < pre.num_clients);
                assert(pre.combiner.get_Responding_idx() == pre.num_clients);
            }
        };
        // So pre.waiting_inv gives us: request_stored(i) || response_stored(i)
        assert(pre.request_stored(i) || pre.response_stored(i));
    };
}

